from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class LoginV1(SchemaObject):
    token = SchemaField(name="token", not_null=True)
    expires_time = SchemaField(name="expires", not_null=True)
    last_login_time = SchemaField(name="last_login", not_null=True)
    last_failed_login = SchemaField(name="last_failed_login", not_null=True)
    failed_login_attempts = SchemaField(name="failed_login_attempts", not_null=True)
    text = SchemaField(name="additional_text", optional=True)

    def __init__(self, token, expires_time, last_login_time, last_failed_login, failed_login_attempts, text):
        self.token = token
        self.expires_time = expires_time
        self.last_login_time = last_login_time
        self.last_failed_login = last_failed_login
        self.failed_login_attempts = failed_login_attempts
        self.text = text

        super(LoginV1, self).__init__()
